#nullable enable // autogenerated

using MVZ2.GameContent.Bosses;
using MVZ2.GameContent.Buffs.Bosses;
using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Modifiers;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.absorbedByKraken)]
    public class AbsorbedByKrakenBuff : BuffDefinition
    {
        public AbsorbedByKrakenBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(VanillaEntityProps.AI_FROZEN, true));
            AddModifier(new BooleanModifier(EngineEntityProps.INVINCIBLE, true));
            AddModifier(new IntModifier(EngineEntityProps.COLLISION_DETECTION, IntegerOperator.BitOr, EntityCollisionHelper.DETECTION_NO_COLLISION));

            var modifier = new IntModifier(VanillaEntityProps.WATER_INTERACTION, IntegerOperator.Set, PROP_WATER_INTERACTION, priority: VanillaModifierPriorities.FORCE);
            modifier.Condition = static v => v >= 0;
            AddModifier(modifier);
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            if (entity.Definition.GetWaterInteraction() == WaterInteraction.REMOVE)
            {
                buff.SetProperty(PROP_WATER_INTERACTION, WaterInteraction.NONE);
            }
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            var krakenID = GetKrakenID(buff);
            var kraken = krakenID?.GetEntity(buff.Level);
            if (!kraken.ExistsAndAlive())
            {
                var effects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL);
                entity.Die(effects, new BuffSourceReference(entity, buff));
                buff.Remove();
                return;
            }

            var targetPosition = Kraken.GetAbsorbTargetPosition(kraken);
            var position = entity.Position;
            var distance = targetPosition - position;

            float moveSpeed = GetMoveSpeed(buff);
            moveSpeed = Mathf.Min(MAX_SPEED, moveSpeed + ACCELERATION);
            var length = distance.magnitude;
            var motion = distance.normalized * Mathf.Min(length, moveSpeed);
            position += motion;
            SetMoveSpeed(buff, moveSpeed);
            entity.Position = position;

            distance = targetPosition - position;

            if (distance.sqrMagnitude <= DISTANCE_THRESOLD_SQR)
            {
                var damageEffects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL, VanillaDamageEffects.NO_DEATH_EFFECTS, VanillaDamageEffects.REMOVE_ON_DEATH);
                entity.Die(damageEffects, new BuffSourceReference(entity, buff));
                if (entity.IsDynamite())
                {
                    kraken.AddBuff<KrakenAbsorbedDynamiteBuff>();
                    entity.PlaySound(VanillaSoundID.fuse);
                }
                buff.Remove();
            }
        }
        public static float GetMoveSpeed(Buff buff) => buff.GetProperty<float>(PROP_MOVE_SPEED);
        public static void SetMoveSpeed(Buff buff, float value) => buff.SetProperty(PROP_MOVE_SPEED, value);
        public static EntityID? GetKrakenID(Buff buff) => buff.GetProperty<EntityID>(PROP_KRAKEN);
        public static void SetKrakenID(Buff buff, EntityID? value) => buff.SetProperty(PROP_KRAKEN, value);
        public const float ACCELERATION = 1;
        public const float MAX_SPEED = 20;
        public const float DISTANCE_THRESOLD_SQR = 400;
        public static readonly VanillaBuffPropertyMeta<float> PROP_MOVE_SPEED = new VanillaBuffPropertyMeta<float>("move_speed");
        public static readonly VanillaBuffPropertyMeta<EntityID> PROP_KRAKEN = new VanillaBuffPropertyMeta<EntityID>("kraken");
        public static readonly VanillaBuffPropertyMeta<int> PROP_WATER_INTERACTION = new VanillaBuffPropertyMeta<int>("water_interaction", -1);
    }
}
